let output = {};
const qf = $('Call \'sub-query-reformulator\'').first().json.output;
const contact = $('sorento-sub-respond-findcontact-respond').first().json;

let userResponse;
let isEscalateBranch = true;
if ($("Edit Fields1").isExecuted)      { userResponse = $("Edit Fields1").first().json.escalate_message; }
else if ($('Edit Fields3').isExecuted) { userResponse = $("Edit Fields3").first().json.escalate_message; }
else if ($('Edit Fields4').isExecuted) { userResponse = $("Edit Fields4").first().json.escalate_message; }
else if ($('Edit Fields5').isExecuted) { userResponse = $("Edit Fields5").first().json.escalate_message; }
else if ($('Edit Fields6').isExecuted) { userResponse = $("Edit Fields6").first().json.escalate_message; }
else { userResponse = $('central-exchange').first().json.response; isEscalateBranch = false; }

function getResultObj() {
  try { if ($('central-exchange').isExecuted) return $('central-exchange').first().json; } catch (e) {}
  try { if ($('validator').isExecuted)        return $('validator').first().json; }        catch (e) {}
  return $input.first().json || {};
}

let response = userResponse;   // escalate/clarification → short, pass through as-is
let last_result_set = [];

if (!isEscalateBranch) {
  const resultObj = getResultObj();
  const answers = Array.isArray(resultObj.answers) ? resultObj.answers : [];
  const domain = qf.domain_hint || 'result';

  if (answers.length === 0) {
    response = `Previous turn (${domain}): no results.`;
  } else {
    const indexed = answers.map((a, i) => {
      const firstLine = (a.description || '').split('\n')[0].replace(/\*/g, '').trim();
      const label = a.promotion_name || a.name || a.product || firstLine || `item ${i + 1}`;
      return {
        idx: i + 1,
        uuid: a.uuid || a.id || null,
        label,
        entity_type: a.entity_type || null,
        product: a.product || null,
        attachment_type: a.attachmentType || a.attachment_type || null,
        filename: a.filename || null,
      };
    });

    const sig = r => `${r.product}||${r.attachment_type}||${r.label}`;
    const allIdentical = new Set(indexed.map(sig)).size === 1;

    if (allIdentical) {
      const s = indexed[0];
      const what = s.attachment_type || s.label || 'records';
      response = `Previous turn (${domain}): returned ${answers.length} ${what} for ${s.product || s.label}.`;
    } else {
      const lines = indexed.map(r => `${r.idx}) ${r.label}`).join('  ');
      response = `Previous turn (${domain}): returned ${answers.length} items: ${lines}`;
    }
    last_result_set = indexed;
  }
}

output = {
  "variables": {
    "message_type": qf.message_type,
    "intent_hint": qf.intent_hint,
    "domain_hint": qf.domain_hint,
    "user_goal": qf.user_goal,
    "query_scope": qf.query_scope,
    "access_levels": qf.access_levels,
    "entities": qf.entities,
    "routing": qf.routing,
    "escalation": qf.escalation,
    "response": response,                 // now the COMPRESSED view (parser-facing)
    "last_result_set": last_result_set,
  }
};
return output;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let is_valid = false
let output = $input.first().json
let semantic_parser = $('Call \'sub-query-reformulator\'').first().json
let domain_hint = semantic_parser.output.domain_hint
output.is_valid = true
if ($('Edit Fields2').isExecuted && $('Edit Fields2').first().json.not_allowed_check_stock) {
  const resultNode = $input.first().json;
  const formulatorNode = $('Call \'sub-query-reformulator\'').first().json;
  const parserOutput = formulatorNode.output ?? formulatorNode;
  const demandQty = Number(parserOutput.demand_qty ?? 0);

  // handle answer records from get-result
  const answers = Array.isArray(resultNode.answers) ? resultNode.answers : [];

  // group by product and sum stock_qty
  const grouped = {};

  for (const item of answers) {
    const product = item.product || 'UNKNOWN_PRODUCT';
    const stockQty = Number(item.stock_qty ?? 0);

    if (!grouped[product]) {
      grouped[product] = {
        product,
        total_stock_qty: 0,
        rows: [],
      };
    }

    grouped[product].total_stock_qty += stockQty;
    grouped[product].rows.push(item);
  }

  // build response_intro lines
  const introLines = Object.values(grouped).map(group => {
    const canFulfill = demandQty <= group.total_stock_qty;
    if (canFulfill) {
      return `Quantity of ${demandQty} for product ${group.product} can be fulfilled.`;
    }
    return `Quantity of ${demandQty} for product ${group.product} cannot be fulfilled. Total available quantity is ${group.total_stock_qty}.`;
  });
  output.response = introLines.join("\n")

}
return output

let output = {};
let input = $input.first().json
if (input.output && typeof input.output === 'object') {
  output = input.output;
} else {
  let raw = String(input.output || input.text || '');
  if (raw) {
    // Remove Markdown code fences like ```json ... ```
    raw = raw.replace(/```[\s\S]*?```/g, match =>
      match.replace(/```json?|\```/g, '')
    );

    const idx = raw.indexOf('{');
    if (idx === -1) {
      output = raw;
      output.quick_reply = input.quick_reply
    } else {
      const startSlice = raw.slice(idx);
      const last = startSlice.lastIndexOf('}');
      const cleanSlice = last !== -1 ? startSlice.slice(0, last + 1) : startSlice;
      output = JSON.parse(cleanSlice);
    }
  } else {
    output = input
  }
}

return output;

let query_reformulator = $('Call \'sub-query-reformulator\'').first().json
let resolved_entities = $('resolve-entity-clarification').first().json.resolutions
let session_vars = $('get-session-vars').first().json.session_vars
let message_type = query_reformulator.output.message_type
let intent_hint = query_reformulator.output.intent_hint
let domain_hint = query_reformulator.output.domain_hint
let entities = resolved_entities.flatMap(res =>
  res.matches?.map(m => ({
    entity_type: m.entity_type,
    canonical_code: m.canonical_code,
  })) || []
)
let input_msg = $('tf-message').first().json.message.message.text || $('tf-message').first().json.message.message.attachment.description
let user_goal = query_reformulator.output.user_goal || input_msg
if (message_type == "casual" || message_type == "unknown") {
  session_vars = {}
} 
return {
  "message_type": message_type,
  "intent_hint": intent_hint,
  "domain_hint": domain_hint,
  "session_vars": session_vars,
  "entities": entities,
  "user_goal": user_goal
}

// ── Domain ↔ Entity-Type Gate (compatibility + required-type) ──────────────
const parser   = $('Call \'sub-query-reformulator\'').first().json.output ?? {};
const domain   = parser.domain_hint ?? null;
const resolver = $('resolve-entity').first().json ?? {};

const ALLOWED = {
  master_products:    ['product', 'category', 'brand'],
  product_attachment: ['product', 'attachment', 'attachment_type', 'category', 'brand'],
  promotion:          ['product', 'promotion', 'category', 'brand'],
  inventory:          ['product', 'category', 'brand'],
  order:              ['order', 'customer_order', 'transporter', 'customer', 'product'],
  incoming:           ['product', 'inbound_shipment', 'category', 'brand'],
  forms:              ['form'],
  portal_link:        [],
};
const ALLOWS_EMPTY = {
  promotion: true, incoming: true, forms: true, portal_link: true,
  master_products: false, product_attachment: false, inventory: false, order: false,
};

// Domains that need a SPECIFIC type present to be scopable (beyond compatibility).
const REQUIRED_TYPES = { product_attachment: ['attachment_type'] };
const TYPE_PROMPT = {
  attachment_type: 'product image, technical drawing, 3D model, or certificate',
};

// Flatten + de-dupe resolver matches.
const flat = [
  ...(resolver.resolutions ?? []).flatMap(r => r.matches ?? []),
  ...(resolver.intersection ?? []),
  ...Object.values(resolver.by_entity_type ?? {}).flat(),
];
const byUuid = {};
for (const m of flat) if (m && m.uuid) byUuid[m.uuid] = { uuid: m.uuid, entity_type: m.entity_type };
const entities = Object.values(byUuid);

const allowed = ALLOWED[domain] ?? null;
let gate_passed = true, gate_reason = 'ok', gate_clarification = '';
let compatible_entities = entities;

if (allowed === null) {
  gate_reason = `domain '${domain}' not in matrix; passing through unscoped`;
} else {
  compatible_entities = entities.filter(e => allowed.includes(e.entity_type));

  if (entities.length === 0) {
    gate_passed = ALLOWS_EMPTY[domain] === true;
    gate_reason = gate_passed ? `no entities; '${domain}' permits broad query`
                              : `no entities and '${domain}' requires a scoping entity`;
  } else if (compatible_entities.length === 0) {
    const got = [...new Set(entities.map(e => e.entity_type))].join(', ');
    gate_passed = false;
    gate_reason = `types [${got}] incompatible with '${domain}'`;
  }
}

// Required-type check (only if still passing). Look in resolver output AND raw parser hints,
// since an attachment_type may be a filter the parser carried, not a UUID-resolved record.
if (gate_passed && Array.isArray(REQUIRED_TYPES[domain])) {
  const haveTypes = new Set([
    ...entities.map(e => e.entity_type),
    ...(parser.entities ?? []).map(e => e.hint),
  ]);
  const missing = REQUIRED_TYPES[domain].filter(t => !haveTypes.has(t));
  if (missing.length > 0) {
    gate_passed = false;
    gate_reason = `'${domain}' requires [${missing.join(', ')}] but none resolved`;

    const subject = (parser.entities ?? []).find(e => e.hint === 'product')?.raw || 'this product';
    gate_clarification = missing.map(t =>
      t === 'attachment_type'
        ? `Please specify which type of attachment you need for ${subject} — e.g. ${TYPE_PROMPT.attachment_type}.`
        : `Please specify the ${t}.`
    ).join(' ');
  }
}

const out = $input.first().json;
out.gate_passed = gate_passed;
out.gate_reason = gate_reason;
out.gate_clarification = gate_clarification;   // '' when nothing to ask
out.compatible_entities = compatible_entities;
out.gate_debug = { domain, allowed_lookup: ALLOWED[domain], entities_count: entities.length };
return out;

const q    = $('Call \'sub-query-reformulator\'').first().json.output;
const r    = $('resolve-entity').first().json ?? {};
const gate = $('disallowed-entity-gate').first().json ?? {};

const resolvedTypes = r?.by_entity_type ? Object.keys(r.by_entity_type) : [];
const parserHints   = Array.isArray(q?.entities) ? q.entities.map(e => e.hint) : [];
const haveAttachmentType =
  resolvedTypes.includes('attachment_type') || parserHints.includes('attachment_type');

const gatePassed = gate.gate_passed !== false;
const gateReason = gate.gate_reason || '';
const allowedTypes = gate?.gate_debug?.allowed_lookup ?? [];

// readable list: ['product','category','brand'] → "product, category, or brand"
const humanList = (arr) => {
  const a = arr.filter(Boolean);
  if (a.length === 0) return 'a valid value';
  if (a.length === 1) return a[0];
  return `${a.slice(0, -1).join(', ')}, or ${a[a.length - 1]}`;
};

const missingAttachmentType =
  q.domain_hint === 'product_attachment' && !gatePassed && !haveAttachmentType;

// NEW: gate failed because the domain needs a scope but none was given
const needsScope =
  !gatePassed && !missingAttachmentType &&
  /requires a scoping entity/.test(gateReason);

let escalate_message;
let is_clarification = false;

if (missingAttachmentType) {
  const subject = Array.isArray(q?.entities) ? q.entities.find(e => e.hint === 'product') : null;
  const subjectText = subject ? `${subject.hint} ${subject.raw}` : 'the requested product';
  escalate_message =
    `Please provide the attachment type for ${subjectText} ` +
    `— e.g. product image, technical drawing, or certificate.`;
  is_clarification = true;

} else if (needsScope) {
  escalate_message =
    `A ${q.domain_hint} enquiry can't be answered with a general search — ` +
    `please specify a ${humanList(allowedTypes)} so I can look it up.`;
  is_clarification = true;

} else {
  // ── existing "could not find … for …" behaviour (unchanged) ──────────────
  const tokens    = Array.isArray(r?.tokens) ? r.tokens : [];
  const tokenText = tokens.join(' ');
  let requested;
  if (resolvedTypes.length && tokenText) {
    requested = `${resolvedTypes.join('/')} ${tokenText}`;
  } else if (tokenText) {
    requested = tokenText;
  } else {
    const entities = Array.isArray(q?.entities) ? q.entities : [];
    requested = entities.length
      ? entities.map(e => `${e.hint || 'item'} ${e.raw}`).join(', ')
      : 'the requested item';
  }
  const dateRange = (q.date_filter_start && q.date_filter_end)
    ? ` from ${q.date_filter_start} to ${q.date_filter_end}` : '';
  const access = q.intent_hint === 'check_promotion'
    ? ` for ${q.access_levels?.join(', ') || 'End User'}` : '';
  const team = q.routing?.suggested_team || 'customer_service';
  escalate_message =
    `Could not find ${q.domain_hint} for ${requested}${dateRange}${access}. ` +
    `Would you like me to escalate to ${team} team?`;
}

const out = $input.first().json;
out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
return out;

const names = Array.isArray($input.first().json.name) ? $input.first().json.name : [];
const q = $('Call \'sub-query-reformulator\'').first().json.output ?? {};
const domain = q.domain_hint || 'this enquiry';

// optional: friendlier labels than the raw domain_hint
const LABELS = {
  promotion: 'promotions',
  master_products: 'product information',
  product_attachment: 'product attachments',
  inventory: 'stock',
  order: 'orders',
  incoming: 'incoming stock',
  forms: 'forms',
  portal_link: 'this request',
};
const domainLabel = LABELS[q.domain_hint] || domain;

let escalate_message;
let is_clarification = false;

if (names.length === 0) {
  escalate_message = `You have no access levels configured to get ${domainLabel}.`;
} else {
  // bullet each option on its own line — easier to read on WhatsApp than comma-joined
  const options = names.map(n => `- ${n}`).join('\n');
  escalate_message =
    `Please specify which access level you'd like to use for ${domainLabel}:\n${options}`;
  is_clarification = true;
}

const out = $input.first().json;
out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
out.quick_reply = names.join(",")
return out;
